<script setup>
import {ref} from 'vue';
import SettingsIcon from './SettingsIcon.vue';
defineProps({preview:String,cover:Boolean,disabled:Boolean,large:Boolean,compact:Boolean,title:String,subtitle:String});const emit=defineEmits(['pick','files','remove']);const dragging=ref(false);
function drop(e){dragging.value=false;emit('files',[...e.dataTransfer.files]);}
</script>
<template><div class="product-drop" :class="{cover,loaded:!!preview,dragging,large,compact}" @dragover.prevent="!disabled&&(dragging=true)" @dragleave.prevent="dragging=false" @drop.prevent="!disabled&&drop($event)"><button type="button" class="product-drop-button" :disabled="disabled" :aria-label="cover?'Elegir portada':'Elegir archivos'" @click="emit('pick')"><img v-if="cover&&preview" :src="preview" alt="Portada del producto"/><template v-else><span class="drop-symbol"><SettingsIcon :name="cover?'image':'upload'"/></span><span class="drop-description"><strong>{{title||(large?'Soltá los archivos del producto':compact?'Agregar más archivos':cover?'Arrastrá una imagen':'Arrastrá los archivos acá o hacé clic para elegirlos *')}}</strong><small>{{subtitle||(large?'El .unitypackage, los .zip y las imágenes, todo junto':cover?'o hacé clic para elegirla':'Podés elegir varios a la vez')}}</small></span><span v-if="large" class="drop-choose-visual">Elegir archivos</span><span v-if="!cover&&!large&&!compact" class="drop-formats">.unitypackage · .zip · .rar · imágenes</span></template></button><div v-if="cover&&preview" class="cover-hover-actions"><button type="button" :disabled="disabled" @click="emit('pick')">Cambiar</button><button type="button" :disabled="disabled" @click="emit('remove')">Quitar</button></div></div></template>
<style>
.product-drop{position:relative;border:1.5px dashed rgba(255,255,255,.18);border-radius:16px;background:rgba(255,255,255,.03);overflow:hidden;transition:background .15s,border-color .15s}.product-drop.cover{width:240px;height:240px;border-radius:18px;border-color:rgba(242,167,195,.45);background:rgba(242,167,195,.05)}.product-drop.dragging{border-style:solid;border-color:var(--accent);background:var(--accent-tint)}.product-drop-button{display:flex;align-items:center;gap:14px;width:100%;min-height:108px;padding:20px;border:0;background:none;color:var(--text);text-align:left;font-family:inherit}.cover .product-drop-button{height:100%;flex-direction:column;justify-content:center;gap:14px;padding:20px;text-align:center}.drop-symbol{display:flex;align-items:center;justify-content:center;width:48px;height:48px;flex:none;border-radius:13px;background:var(--accent-tint);color:var(--accent)}.cover .drop-symbol{width:52px;height:52px}.drop-symbol svg{width:24px;height:24px}.drop-description{display:flex;flex-direction:column;gap:8px}.drop-description strong{font-size:15px;font-weight:700;line-height:1.6}.cover .drop-description strong{font-size:14px}.drop-description small{font-size:12px;color:var(--text-muted);line-height:1.6}.drop-formats{font:11px 'JetBrains Mono',monospace;color:var(--text-muted);margin-left:auto;max-width:135px;line-height:1.9;flex:none}.cover.loaded .product-drop-button{padding:0}.cover .product-drop-button img{display:block;width:100%;height:100%;object-fit:cover}.cover-hover-actions{position:absolute;bottom:0;left:0;right:0;display:flex;align-items:center;justify-content:center;gap:8px;padding:30px 10px 12px;background:linear-gradient(transparent,rgba(10,6,16,.85));opacity:0;transition:opacity .15s;pointer-events:none}.product-drop:hover .cover-hover-actions,.product-drop:focus-within .cover-hover-actions{opacity:1;pointer-events:auto}.cover-hover-actions button{min-height:44px;padding:0 14px;border-radius:12px;background:#33263ee8;border:1px solid #ffffff24;color:var(--text);font:12px 'Plus Jakarta Sans',sans-serif}.product-drop-button:focus-visible{outline:2px solid var(--accent);outline-offset:-5px}.cover-hover-actions button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}@media(max-width:719px){.drop-formats{display:none}.product-drop-button{padding:17px;gap:12px}}@media(hover:none){.cover-hover-actions{opacity:1;pointer-events:auto}}
</style>
